from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any

import yaml


@dataclass(frozen=True)
class RunConfig:
    raw: dict[str, Any]
    tiny: bool = False

    @property
    def seed(self) -> int:
        return int(self.raw.get("seed", 0))

    @property
    def model_backend(self) -> str:
        if self.tiny:
            return str(self.raw.get("tiny", {}).get("backend", "tiny"))
        return str(self.raw.get("model", {}).get("backend", "hf"))

    @property
    def model_name(self) -> str:
        return str(self.raw.get("model", {}).get("name", "google/gemma-2-2b"))

    @property
    def device(self) -> str:
        return str(self.raw.get("model", {}).get("device", "auto"))

    @property
    def dtype(self) -> str:
        return str(self.raw.get("model", {}).get("dtype", "auto"))

    @property
    def stories_dir(self) -> Path:
        return Path(self.raw.get("data", {}).get("stories_dir", "data/stories"))

    @property
    def emotions(self) -> list[str]:
        section = self.raw.get("tiny" if self.tiny else "scale", {})
        return list(section.get("emotions", []))

    @property
    def topics(self) -> int:
        section = self.raw.get("tiny" if self.tiny else "scale", {})
        return int(section.get("topics", 0))

    @property
    def stories_per_cell(self) -> int:
        section = self.raw.get("tiny" if self.tiny else "scale", {})
        return int(section.get("stories_per_cell", 0))

    @property
    def token_start(self) -> int:
        if self.tiny:
            return int(self.raw.get("tiny", {}).get("token_start", 12))
        return int(self.raw.get("data", {}).get("token_start", 50))

    @property
    def pc_variance_threshold(self) -> float:
        return float(self.raw.get("extraction", {}).get("pc_variance_threshold", 0.5))

    @property
    def validation_layer_fraction(self) -> float:
        return float(self.raw.get("extraction", {}).get("layer_fraction_for_validation", 0.67))

    @property
    def steering_strength(self) -> float:
        return float(self.raw.get("steering", {}).get("strength", 0.8))


def load_config(path: str | Path, tiny: bool = False) -> RunConfig:
    with Path(path).open("r", encoding="utf-8") as f:
        raw = yaml.safe_load(f) or {}
    return RunConfig(raw=raw, tiny=tiny)

from __future__ import annotations

import numpy as np


def mean_subtracted_vectors(activation_by_emotion: dict[str, np.ndarray]) -> dict[str, np.ndarray]:
    """Return emotion means minus the grand mean across emotion means."""
    if not activation_by_emotion:
        raise ValueError("activation_by_emotion must not be empty")
    keys = list(activation_by_emotion)
    stacked = np.stack([activation_by_emotion[k] for k in keys], axis=0)
    grand = stacked.mean(axis=0)
    return {k: activation_by_emotion[k] - grand for k in keys}


def pca_components_for_variance(x: np.ndarray, threshold: float = 0.5) -> np.ndarray:
    """Compute right-singular principal components explaining at least threshold variance."""
    if x.ndim != 2:
        raise ValueError("x must be a 2D matrix")
    if not 0 <= threshold <= 1:
        raise ValueError("threshold must be in [0, 1]")
    centered = x - x.mean(axis=0, keepdims=True)
    if np.allclose(centered, 0):
        return np.zeros((0, x.shape[1]), dtype=float)
    _, s, vt = np.linalg.svd(centered, full_matrices=False)
    variances = s**2
    total = variances.sum()
    if total <= 0:
        return np.zeros((0, x.shape[1]), dtype=float)
    cumulative = np.cumsum(variances) / total
    n = int(np.searchsorted(cumulative, threshold, side="left") + 1)
    return vt[:n]


def project_out_components(vectors: np.ndarray, components: np.ndarray) -> np.ndarray:
    """Remove the span of row-wise orthonormal components from vectors."""
    if components.size == 0:
        return vectors.copy()
    q, _ = np.linalg.qr(components.T)
    return vectors - (vectors @ q) @ q.T


def cosine_similarity_matrix(vectors: np.ndarray, activations: np.ndarray, eps: float = 1e-12) -> np.ndarray:
    v = vectors / np.maximum(np.linalg.norm(vectors, axis=1, keepdims=True), eps)
    a = activations / np.maximum(np.linalg.norm(activations, axis=1, keepdims=True), eps)
    return v @ a.T


def vector_norm_mean(x: np.ndarray) -> float:
    return float(np.linalg.norm(x, axis=-1).mean())

from __future__ import annotations

import itertools
import math


def expected_score(ra: float, rb: float) -> float:
    return 1.0 / (1.0 + 10 ** ((rb - ra) / 400.0))


def update_elo(ra: float, rb: float, score_a: float, k: float = 24.0) -> tuple[float, float]:
    ea = expected_score(ra, rb)
    eb = 1.0 - ea
    return ra + k * (score_a - ea), rb + k * ((1.0 - score_a) - eb)


def pairwise_probability(logit_a: float, logit_b: float) -> float:
    diff = max(-60.0, min(60.0, logit_a - logit_b))
    return 1.0 / (1.0 + math.exp(-diff / 20.0))


def compute_elo_from_logits(items: list[dict], logits: dict[str, float], rounds: int = 6, k: float = 24.0) -> dict[str, float]:
    ratings = {item["name"]: 1000.0 for item in items}
    pairs = list(itertools.combinations([item["name"] for item in items], 2))
    for _ in range(rounds):
        for a, b in pairs:
            pa = pairwise_probability(logits[a], logits[b])
            ratings[a], ratings[b] = update_elo(ratings[a], ratings[b], pa, k=k)
    return ratings
